@startuml

class GasStation {
  + ID : int
  + Address : string
}

class FuelPump {
  + Number : int
  + IsSelfService : boolean
}

class Fuel {
  + Name : string
  + OctaneRating : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : double
}

class FuelPurchase {
  + ID : int
  + LitersDispensed : double
}

GasStation "1" -- "1..12" FuelPump
FuelPump "1" -- "*" Fuel
GasStation "1" -- "*" DailyPrice
Fuel "1" -- "*" DailyPrice
DailyPrice "1" -- "*" FuelPurchase
FuelPump "1" -- "*" FuelPurchase
FuelPurchase "*" -- "1" Fuel

@enduml

